<template><view :data-skin="scenicSkin" class="visual-page safe cast"><TopBar title="人物档案" eyebrow="THE PEOPLE BUILDING A HOME" @back="back" @settings="settings"/><view class="cast-content"><view class="cast-list"><button role="button" tabindex="0" v-for="c in characters" :key="c.id" :class="{active:c.id===selected}" @click="selected=c.id"><text>{{c.name}}</text><text>{{c.title.split(' / ')[0]}}</text></button></view><view class="cast-scene"><image :src="character.hero" mode="aspectFill"/><view class="caption"><text class="name">{{character.name}}</text><text>{{character.title}}</text><text class="quote">“{{character.summary}}”</text><text class="note">世界观场景示意 · 人物设定档案</text></view></view></view></view></template>
<script setup lang="ts">import {computed,ref} from 'vue';import TopBar from '../../components/TopBar.vue';import {characters} from '../../data/characters';import {goBack} from '../../utils/navigation';const selected=ref('xuzhiwei'),character=computed(()=>characters.find(c=>c.id===selected.value)||characters[0]);function back(){goBack()}function settings(){uni.navigateTo({url:'/pages/settings/index'})}</script>
<style scoped>.cast{background:var(--bg)}.cast-content{display:grid;grid-template-columns:230px 1fr;gap:30px;padding:25px 5vw 45px}.cast-list button{width:100%;margin:0 0 9px;padding:14px 18px;background:var(--panel);color:var(--text);border:1px solid var(--line);border-radius:0;text-align:left}.cast-list button.active{border-color:var(--gold);background:var(--panel-2)}.cast-list text{display:block;font:18px/1.7 serif}.cast-list text+text{font:10px/1.8 sans-serif;color:var(--muted)}.cast-scene{position:relative;min-height:620px;overflow:hidden}.cast-scene image{position:absolute;width:100%;height:100%}.caption{position:absolute;inset:auto 0 0;padding:100px 35px 35px;background:linear-gradient(transparent,#101d1cf5);color:#f2e5ca}.caption>text{display:block;font-size:13px;line-height:1.9}.caption .name{font:38px/1.6 serif}.caption .quote{font:20px/1.9 serif;margin-top:16px}.caption .note{font-size:10px;opacity:.6;margin-top:20px}@media(max-width:700px){.cast-content{display:flex;flex-direction:column-reverse;padding:15px 22px}.cast-list{display:grid;grid-template-columns:1fr 1fr;gap:8px}.cast-scene{min-height:470px}.caption{padding:100px 22px 25px}.caption .quote{font-size:17px}}</style>
